inline void paintPiece(QPainter& p,int piece,int x,int y,int scale){if(!piece)return;const auto& rows=Sprites[std::abs(piece)];p.setPen(Qt::NoPen);p.setBrush(piece>0?QColor("#0b2015"):QColor("#170e24"));for(int r=0;r<16;++r)for(int c=0;c<16;++c)if(rows[r][c]=='1')p.drawRect(x+c*scale-1,y+r*scale-1,scale+2,scale+2);p.setBrush(piece>0?QColor("#e7f2bc"):QColor("#daa6f6"));for(int r=0;r<16;++r)for(int c=0;c<16;++c)if(rows[r][c]=='1')p.drawRect(x+c*scale,y+r*scale,scale,scale);if(piece<0)p.fillRect(x+4*scale,y+14*scale,8*scale,scale,QColor("#59396c"));}
